examples.template:
MonarchAiPromptInput(
    label = {{label}},
    state = prompt,
    onSubmit = {},
    sendIcon = { MonarchIcon(SampleIcons.ArrowUp, contentDescription = null) },
    toolbar = {
        MonarchAiPromptToolbar {
            MonarchAiPromptToolbarToggle(
                text = {{toggle}},
                checked = web,
                onCheckedChange = { web = it },
                icon = { MonarchIcon(SampleIcons.Search, contentDescription = null) },
            )
            MonarchAiPromptToolbarButton(
                text = {{button}},
                onClick = {},
                icon = { MonarchIcon(SampleIcons.List, contentDescription = null) },
            )
        }
    },
)

